static void test_sc_reduce()
{
    std::cout << std::endl << "=== sc_reduce ===" << std::endl;

    // 32-byte path
    unsigned char buf32_1[32];
    std::memcpy(buf32_1, test_vectors::sc_reduce32_in1, 32);
    sc_reduce(buf32_1, 32);
    check_bytes("sc_reduce(l + 12345, 32)", test_vectors::sc_reduce32_out1, buf32_1, 32);

    unsigned char buf32_2[32];
    std::memcpy(buf32_2, test_vectors::sc_reduce32_in2, 32);
    sc_reduce(buf32_2, 32);
    check_bytes("sc_reduce(2^255 - 1, 32)", test_vectors::sc_reduce32_out2, buf32_2, 32);

    // 64-byte path
    unsigned char buf64_1[64];
    std::memcpy(buf64_1, test_vectors::sc_reduce_in1, 64);
    sc_reduce(buf64_1, 64);
    check_bytes("sc_reduce(a*b as 64 bytes, 64)", test_vectors::sc_reduce_out1, buf64_1, 32);

    unsigned char buf64_2[64];
    std::memcpy(buf64_2, test_vectors::sc_reduce_in2, 64);
    sc_reduce(buf64_2, 64);
    check_bytes("sc_reduce(2^511 - 1, 64)", test_vectors::sc_reduce_out2, buf64_2, 32);
}

