static void test_fe_roundtrip()
{
    std::cout << std::endl << "=== fe_frombytes + fe_tobytes roundtrip ===" << std::endl;

    auto roundtrip = [](const char *name, const unsigned char *input, const unsigned char *expected)
    {
        fe f;
        unsigned char out[32];
        fe_frombytes(f, input);
        fe_tobytes(out, f);
        check_bytes(name, expected, out, 32);
    };

    roundtrip("roundtrip(42)", test_vectors::fe_rt_in1, test_vectors::fe_rt_out1);
    roundtrip("roundtrip(p-1)", test_vectors::fe_rt_in2, test_vectors::fe_rt_out2);
    roundtrip("roundtrip(p)", test_vectors::fe_rt_in3, test_vectors::fe_rt_out3);
    roundtrip("roundtrip(p+1)", test_vectors::fe_rt_in4, test_vectors::fe_rt_out4);
    roundtrip("roundtrip(2^255+100)", test_vectors::fe_rt_in5, test_vectors::fe_rt_out5);
}


