static void test_ge_check_subgroup_precomp_vartime()
{
    std::cout << std::endl << "=== ge_check_subgroup_precomp_vartime ===" << std::endl;

    // Sanity check: verify l*G = identity using ge_scalarmult_ct
    {
        const unsigned char l_scalar[] = {0xed, 0xd3, 0xf5, 0x5c, 0x1a, 0x63, 0x12, 0x58, 0xd6, 0x9c, 0xf7,
                                          0xa2, 0xde, 0xf9, 0xde, 0x14, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
                                          0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x10};
        const unsigned char identity_bytes[] = {0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
                                                0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
                                                0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
        ge_p3 G;
        ge_frombytes_vartime(&G, test_vectors::scalarmult_expected_one);
        ge_p1p1 lG;
        ge_scalarmult_ct(&lG, l_scalar, &G);
        ge_p3 lG_p3;
        ge_p1p1_to_p3(&lG_p3, &lG);
        unsigned char lG_bytes[32];
        ge_p3_tobytes(lG_bytes, &lG_p3);
        check_bytes("l*G = identity (sanity check)", identity_bytes, lG_bytes, 32);
    }

    auto check_subgroup = [](const char *name, const unsigned char *point_bytes, int expected)
    {
        ge_p3 p3;
        ge_dsmp table;

        int rc = ge_frombytes_vartime(&p3, point_bytes);
        check_int((std::string(name) + " decode rc").c_str(), 0, rc);

        ge_dsm_precomp(table, &p3);
        int result = ge_check_subgroup_precomp_vartime(table);

        if (expected == 0)
            check_int(name, 0, result);
        else
            check_nonzero(name, result);
    };

    // Points in the prime-order subgroup (multiples of G — should return 0)
    check_subgroup("base point G in subgroup", test_vectors::scalarmult_expected_one, 0);
    check_subgroup("pubkey1 in subgroup", test_vectors::scalarmult_expected1, 0);
    check_subgroup("pubkey2 in subgroup", test_vectors::scalarmult_expected2, 0);

    // Identity point (0, 1) — order 1, trivially in every subgroup
    const unsigned char identity_point[] = {0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
                                            0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
                                            0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
    check_subgroup("identity point in subgroup", identity_point, 0);

    // Small-order point (0, -1) — order 2, NOT in prime-order subgroup
    // y = p - 1 = 2^255 - 20, x = 0
    const unsigned char order2_point[] = {0xec, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff,
                                          0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff,
                                          0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0x7f};
    check_subgroup("order-2 point (0,-1) not in subgroup", order2_point, 1);

    // Small-order point with y = 0 — order 4, NOT in prime-order subgroup
    // y = 0, x = sqrt(-1) (even, so sign bit = 0)
    const unsigned char order4_point[] = {0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
                                          0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
                                          0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
    check_subgroup("order-4 point (sqrt(-1),0) not in subgroup", order4_point, 1);
}

static void test_ge_check_subgroup_precomp_negate_vartime()
{
    std::cout << std::endl << "=== ge_check_subgroup_precomp_negate_vartime ===" << std::endl;

    auto check_subgroup_negate = [](const char *name, const unsigned char *point_bytes, int expected)
    {
        ge_p3 p3;
        ge_dsmp table;

        int rc = ge_frombytes_vartime(&p3, point_bytes);
        check_int((std::string(name) + " decode rc").c_str(), 0, rc);

        // Negate: (X, Y, Z, T) -> (-X, Y, Z, -T)
        fe_neg(p3.X, p3.X);
        fe_neg(p3.T, p3.T);

        ge_dsm_precomp(table, &p3);
        int result = ge_check_subgroup_precomp_negate_vartime(table);

        if (expected == 0)
            check_int(name, 0, result);
        else
            check_nonzero(name, result);
    };

    // Points in the prime-order subgroup (multiples of G — should return 0)
    check_subgroup_negate("negate: base point G in subgroup", test_vectors::scalarmult_expected_one, 0);
    check_subgroup_negate("negate: pubkey1 in subgroup", test_vectors::scalarmult_expected1, 0);
    check_subgroup_negate("negate: pubkey2 in subgroup", test_vectors::scalarmult_expected2, 0);

    // Identity point (0, 1) — order 1, trivially in every subgroup
    const unsigned char identity_point[] = {0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
                                            0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
                                            0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
    check_subgroup_negate("negate: identity point in subgroup", identity_point, 0);

    // Small-order point (0, -1) — order 2, NOT in prime-order subgroup
    const unsigned char order2_point[] = {0xec, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff,
                                          0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff,
                                          0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0x7f};
    check_subgroup_negate("negate: order-2 point (0,-1) not in subgroup", order2_point, 1);

    // Small-order point with y = 0 — order 4, NOT in prime-order subgroup
    const unsigned char order4_point[] = {0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
                                          0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
                                          0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
    check_subgroup_negate("negate: order-4 point (sqrt(-1),0) not in subgroup", order4_point, 1);
}

