static void test_ge_scalarmult_ct_batch()
{
    std::cout << std::endl << "=== ge_scalarmult_ct_batch ===" << std::endl;

    // Test batch CT scalarmult against individual results for various counts
    const size_t test_counts[] = {0, 1, 2, 3, 4, 5, 7, 8, 9, 15, 16, 17};

    for (size_t tc = 0; tc < sizeof(test_counts) / sizeof(test_counts[0]); tc++)
    {
        size_t count = test_counts[tc];
        if (count == 0)
        {
            // Just verify it doesn't crash
            ge_scalarmult_ct_batch(nullptr, nullptr, nullptr, 0);
            continue;
        }

        // Generate test scalars and points
        std::vector<unsigned char> scalars(count * 32);
        std::vector<ge_p3> points(count);
        for (size_t i = 0; i < count; i++)
        {
            // Deterministic test data
            for (int j = 0; j < 32; j++)
                scalars[i * 32 + j] = static_cast<unsigned char>((i * 37 + j * 13 + 7) & 0xFF);
            scalars[i * 32 + 31] &= 0x7F; // Ensure scalar[31] <= 127

            // Generate point: scalar_base * G
            unsigned char base_scalar[32];
            for (int j = 0; j < 32; j++)
                base_scalar[j] = static_cast<unsigned char>((i * 53 + j * 11 + 3) & 0xFF);
            base_scalar[0] &= 248;
            base_scalar[31] &= 127;
            base_scalar[31] |= 64;
            ge_p1p1 tmp;
            ge_scalarmult_base_ct(&tmp, base_scalar);
            ge_p1p1_to_p3(&points[i], &tmp);
        }

        // Compute individual results
        std::vector<ge_p2> expected(count);
        for (size_t i = 0; i < count; i++)
        {
            ge_p1p1 tmp;
            ge_scalarmult_ct(&tmp, scalars.data() + i * 32, &points[i]);
            ge_p1p1_to_p2(&expected[i], &tmp);
        }

        // Compute batch results
        std::vector<ge_p2> batch_results(count);
        ge_scalarmult_ct_batch(batch_results.data(), scalars.data(), points.data(), count);

        // Compare: serialize both to bytes and check
        for (size_t i = 0; i < count; i++)
        {
            unsigned char expected_bytes[32], batch_bytes[32];
            ge_tobytes(expected_bytes, &expected[i]);
            ge_tobytes(batch_bytes, &batch_results[i]);
            std::string name = "batch CT count=" + std::to_string(count) + " idx=" + std::to_string(i);
            check_bytes(name.c_str(), expected_bytes, batch_bytes, 32);
        }
    }
}

