static void test_ge_dsm_negate_vartime_batch()
{
    std::cout << std::endl << "=== ge_double_scalarmult_negate_vartime_batch ===" << std::endl;

    const size_t test_counts[] = {0, 1, 2, 3, 4, 5, 7, 8, 9, 15, 16, 17};

    for (size_t tc = 0; tc < sizeof(test_counts) / sizeof(test_counts[0]); tc++)
    {
        size_t count = test_counts[tc];
        if (count == 0)
        {
            ge_double_scalarmult_negate_vartime_batch(nullptr, nullptr, nullptr, nullptr, nullptr, 0);
            continue;
        }

        std::vector<unsigned char> a_scalars(count * 32);
        std::vector<unsigned char> b_scalars(count * 32);
        std::vector<ge_p3> A_points(count);
        std::vector<ge_p3> B_points(count);
        for (size_t i = 0; i < count; i++)
        {
            for (int j = 0; j < 32; j++)
            {
                a_scalars[i * 32 + j] = static_cast<unsigned char>((i * 41 + j * 17 + 5) & 0xFF);
                b_scalars[i * 32 + j] = static_cast<unsigned char>((i * 59 + j * 23 + 11) & 0xFF);
            }
            a_scalars[i * 32 + 31] &= 0x7F;
            b_scalars[i * 32 + 31] &= 0x7F;

            // Generate A point
            unsigned char base_scalar_a[32];
            for (int j = 0; j < 32; j++)
                base_scalar_a[j] = static_cast<unsigned char>((i * 67 + j * 19 + 13) & 0xFF);
            base_scalar_a[0] &= 248;
            base_scalar_a[31] &= 127;
            base_scalar_a[31] |= 64;
            ge_p1p1 tmp;
            ge_scalarmult_base_ct(&tmp, base_scalar_a);
            ge_p1p1_to_p3(&A_points[i], &tmp);

            // Generate B point (different seed)
            unsigned char base_scalar_b[32];
            for (int j = 0; j < 32; j++)
                base_scalar_b[j] = static_cast<unsigned char>((i * 71 + j * 29 + 17) & 0xFF);
            base_scalar_b[0] &= 248;
            base_scalar_b[31] &= 127;
            base_scalar_b[31] |= 64;
            ge_scalarmult_base_ct(&tmp, base_scalar_b);
            ge_p1p1_to_p3(&B_points[i], &tmp);
        }

        // Compute individual results using single-op with ge_dsm_precomp
        std::vector<ge_p2> expected(count);
        for (size_t i = 0; i < count; i++)
        {
            ge_dsmp Bi;
            ge_dsm_precomp(Bi, &B_points[i]);
            ge_p1p1 tmp;
            ge_double_scalarmult_negate_vartime(
                &tmp, a_scalars.data() + i * 32, &A_points[i], b_scalars.data() + i * 32, Bi);
            ge_p1p1_to_p2(&expected[i], &tmp);
        }

        // Compute batch results
        std::vector<ge_p2> batch_results(count);
        ge_double_scalarmult_negate_vartime_batch(
            batch_results.data(), a_scalars.data(), A_points.data(), b_scalars.data(), B_points.data(), count);

        for (size_t i = 0; i < count; i++)
        {
            unsigned char expected_bytes[32], batch_bytes[32];
            ge_tobytes(expected_bytes, &expected[i]);
            ge_tobytes(batch_bytes, &batch_results[i]);
            std::string name = "batch DSM-gen count=" + std::to_string(count) + " idx=" + std::to_string(i);
            check_bytes(name.c_str(), expected_bytes, batch_bytes, 32);
        }
    }
}

