// ==============================================
// Multi-Scalar Multiplication (MSM)
// ==============================================

static void test_ge_multiscalar_mul_vartime()
{
    std::cout << std::endl << "=== ge_multiscalar_mul_vartime ===" << std::endl;

    // n=0 → identity
    {
        ge_p3 result;
        ge_multiscalar_mul_vartime(&result, nullptr, nullptr, 0);
        unsigned char out[32];
        ge_p3_tobytes(out, &result);
        const unsigned char identity[32] = {0x01};
        check_bytes("MSM n=0 → identity", identity, out, 32);
    }

    // n=1 → matches ge_scalarmult_ct
    {
        unsigned char scalar[32];
        for (int j = 0; j < 32; j++)
            scalar[j] = static_cast<unsigned char>((j * 13 + 7) & 0xFF);
        scalar[31] &= 0x7F;

        unsigned char base_scalar[32];
        for (int j = 0; j < 32; j++)
            base_scalar[j] = static_cast<unsigned char>((j * 11 + 3) & 0xFF);
        base_scalar[0] &= 248;
        base_scalar[31] &= 127;
        base_scalar[31] |= 64;
        ge_p1p1 tmp;
        ge_p3 point;
        ge_scalarmult_base_ct(&tmp, base_scalar);
        ge_p1p1_to_p3(&point, &tmp);

        // Reference: single scalarmult
        ge_scalarmult_ct(&tmp, scalar, &point);
        ge_p3 ref_p3;
        ge_p1p1_to_p3(&ref_p3, &tmp);
        unsigned char expected[32];
        ge_p3_tobytes(expected, &ref_p3);

        // MSM
        ge_p3 msm_result;
        ge_multiscalar_mul_vartime(&msm_result, scalar, &point, 1);
        unsigned char actual[32];
        ge_p3_tobytes(actual, &msm_result);

        check_bytes("MSM n=1 matches scalarmult_ct", expected, actual, 32);
    }

    // n=2 → matches two individual scalarmults summed
    {
        unsigned char scalars[64];
        ge_p3 points[2];
        for (int i = 0; i < 2; i++)
        {
            for (int j = 0; j < 32; j++)
                scalars[i * 32 + j] = static_cast<unsigned char>((i * 37 + j * 13 + 7) & 0xFF);
            scalars[i * 32 + 31] &= 0x7F;

            unsigned char bs[32];
            for (int j = 0; j < 32; j++)
                bs[j] = static_cast<unsigned char>((i * 53 + j * 11 + 3) & 0xFF);
            bs[0] &= 248;
            bs[31] &= 127;
            bs[31] |= 64;
            ge_p1p1 tmp;
            ge_scalarmult_base_ct(&tmp, bs);
            ge_p1p1_to_p3(&points[i], &tmp);
        }

        // Reference: s0*P0 + s1*P1
        ge_p1p1 tmp;
        ge_p3 r0, r1;
        ge_scalarmult_ct(&tmp, scalars, &points[0]);
        ge_p1p1_to_p3(&r0, &tmp);
        ge_scalarmult_ct(&tmp, scalars + 32, &points[1]);
        ge_p1p1_to_p3(&r1, &tmp);
        ge_cached cached;
        ge_p3_to_cached(&cached, &r1);
        ge_add(&tmp, &r0, &cached);
        ge_p3 ref;
        ge_p1p1_to_p3(&ref, &tmp);
        unsigned char expected[32];
        ge_p3_tobytes(expected, &ref);

        ge_p3 msm_result;
        ge_multiscalar_mul_vartime(&msm_result, scalars, points, 2);
        unsigned char actual[32];
        ge_p3_tobytes(actual, &msm_result);

        check_bytes("MSM n=2 matches sum of scalarmults", expected, actual, 32);
    }

    // Various N values — cross-validate against serial computation
    const size_t test_counts[] = {3, 4, 5, 7, 8, 9, 15, 16, 17, 31, 32, 33, 64, 100};
    for (size_t tc = 0; tc < sizeof(test_counts) / sizeof(test_counts[0]); tc++)
    {
        size_t count = test_counts[tc];

        std::vector<unsigned char> scalars(count * 32);
        std::vector<ge_p3> points(count);
        for (size_t i = 0; i < count; i++)
        {
            for (int j = 0; j < 32; j++)
                scalars[i * 32 + j] = static_cast<unsigned char>((i * 37 + j * 13 + 7) & 0xFF);
            scalars[i * 32 + 31] &= 0x7F;

            unsigned char bs[32];
            for (int j = 0; j < 32; j++)
                bs[j] = static_cast<unsigned char>((i * 53 + j * 11 + 3) & 0xFF);
            bs[0] &= 248;
            bs[31] &= 127;
            bs[31] |= 64;
            ge_p1p1 tmp;
            ge_scalarmult_base_ct(&tmp, bs);
            ge_p1p1_to_p3(&points[i], &tmp);
        }

        // Reference: serial scalarmults + additions
        ge_p3 serial_result;
        {
            ge_p1p1 tmp;
            ge_scalarmult_ct(&tmp, scalars.data(), &points[0]);
            ge_p1p1_to_p3(&serial_result, &tmp);
            for (size_t i = 1; i < count; i++)
            {
                ge_p3 ri;
                ge_scalarmult_ct(&tmp, scalars.data() + i * 32, &points[i]);
                ge_p1p1_to_p3(&ri, &tmp);
                ge_cached cached;
                ge_p3_to_cached(&cached, &ri);
                ge_add(&tmp, &serial_result, &cached);
                ge_p1p1_to_p3(&serial_result, &tmp);
            }
        }
        unsigned char expected[32];
        ge_p3_tobytes(expected, &serial_result);

        ge_p3 msm_result;
        ge_multiscalar_mul_vartime(&msm_result, scalars.data(), points.data(), count);
        unsigned char actual[32];
        ge_p3_tobytes(actual, &msm_result);

        std::string name = "MSM n=" + std::to_string(count);
        check_bytes(name.c_str(), expected, actual, 32);
    }

    // Edge case: zero scalars (all zeros → identity)
    {
        unsigned char zero_scalar[32] = {};
        unsigned char bs[32];
        for (int j = 0; j < 32; j++)
            bs[j] = static_cast<unsigned char>((j * 11 + 3) & 0xFF);
        bs[0] &= 248;
        bs[31] &= 127;
        bs[31] |= 64;
        ge_p1p1 tmp;
        ge_p3 point;
        ge_scalarmult_base_ct(&tmp, bs);
        ge_p1p1_to_p3(&point, &tmp);

        ge_p3 result;
        ge_multiscalar_mul_vartime(&result, zero_scalar, &point, 1);
        unsigned char out[32];
        ge_p3_tobytes(out, &result);
        const unsigned char identity[32] = {0x01};
        check_bytes("MSM zero scalar → identity", identity, out, 32);
    }

    // Edge case: all-same-point, verify same as serial
    {
        const size_t count = 4;
        unsigned char bs[32];
        for (int j = 0; j < 32; j++)
            bs[j] = static_cast<unsigned char>((j * 17 + 5) & 0xFF);
        bs[0] &= 248;
        bs[31] &= 127;
        bs[31] |= 64;
        ge_p1p1 tmp;
        ge_p3 P;
        ge_scalarmult_base_ct(&tmp, bs);
        ge_p1p1_to_p3(&P, &tmp);

        unsigned char scalars[128];
        ge_p3 points[4];
        for (size_t i = 0; i < count; i++)
        {
            for (int j = 0; j < 32; j++)
                scalars[i * 32 + j] = static_cast<unsigned char>((i * 41 + j * 7 + 3) & 0xFF);
            scalars[i * 32 + 31] &= 0x7F;
            points[i] = P;
        }

        // Reference: serial computation s0*P + s1*P + s2*P + s3*P
        ge_p3 serial_result;
        ge_scalarmult_ct(&tmp, scalars, &P);
        ge_p1p1_to_p3(&serial_result, &tmp);
        for (size_t i = 1; i < count; i++)
        {
            ge_p3 ri;
            ge_scalarmult_ct(&tmp, scalars + i * 32, &points[i]);
            ge_p1p1_to_p3(&ri, &tmp);
            ge_cached cached;
            ge_p3_to_cached(&cached, &ri);
            ge_add(&tmp, &serial_result, &cached);
            ge_p1p1_to_p3(&serial_result, &tmp);
        }
        unsigned char expected[32];
        ge_p3_tobytes(expected, &serial_result);

        ge_p3 msm_result;
        ge_multiscalar_mul_vartime(&msm_result, scalars, points, count);
        unsigned char actual[32];
        ge_p3_tobytes(actual, &msm_result);

        check_bytes("MSM same-point: serial reference", expected, actual, 32);
    }
}

