static void test_scalarmult_zero_scalar()
{
    std::cout << std::endl << "=== scalarmult: zero scalar ===" << std::endl;

    // The identity point encoding: Y=1, X=0 → 01 00 00 ... 00
    const unsigned char identity[32] = {0x01};

    // 0 * G should give identity
    {
        unsigned char zero[32] = {};
        ge_p1p1 r;
        ge_p3 p3;
        unsigned char out[32];

        ge_scalarmult_base_ct(&r, zero);
        ge_p1p1_to_p3(&p3, &r);
        ge_p3_tobytes(out, &p3);
        check_bytes("0 * G = identity (base_ct)", identity, out, 32);
    }

    // 0 * A should give identity (for a known point A)
    {
        unsigned char zero[32] = {};
        unsigned char base_scalar[32] = {};
        base_scalar[0] = 9;
        base_scalar[0] &= 248;
        base_scalar[31] &= 127;
        base_scalar[31] |= 64;

        ge_p1p1 tmp;
        ge_p3 A;
        ge_scalarmult_base_ct(&tmp, base_scalar);
        ge_p1p1_to_p3(&A, &tmp);

        ge_p1p1 r;
        ge_p3 p3;
        unsigned char out[32];
        ge_scalarmult_ct(&r, zero, &A);
        ge_p1p1_to_p3(&p3, &r);
        ge_p3_tobytes(out, &p3);
        check_bytes("0 * A = identity (scalarmult_ct)", identity, out, 32);
    }
}

