static void test_batch_matches_single()
{
    std::cout << std::endl << "=== batch vs single cross-validation ===" << std::endl;

    // Test batch CT scalarmult matches single-op for N=1..8
    for (size_t count = 1; count <= 8; count++)
    {
        std::vector<unsigned char> scalars(count * 32);
        std::vector<ge_p3> points(count);
        for (size_t i = 0; i < count; i++)
        {
            for (int j = 0; j < 32; j++)
                scalars[i * 32 + j] = static_cast<unsigned char>((i * 71 + j * 31 + 17) & 0xFF);
            scalars[i * 32 + 31] &= 0x7F;

            unsigned char base_scalar[32];
            for (int j = 0; j < 32; j++)
                base_scalar[j] = static_cast<unsigned char>((i * 89 + j * 7 + 29) & 0xFF);
            base_scalar[0] &= 248;
            base_scalar[31] &= 127;
            base_scalar[31] |= 64;
            ge_p1p1 tmp;
            ge_scalarmult_base_ct(&tmp, base_scalar);
            ge_p1p1_to_p3(&points[i], &tmp);
        }

        // Single-op results
        std::vector<unsigned char> single_bytes(count * 32);
        for (size_t i = 0; i < count; i++)
        {
            ge_p1p1 tmp;
            ge_scalarmult_ct(&tmp, scalars.data() + i * 32, &points[i]);
            ge_p2 p2;
            ge_p1p1_to_p2(&p2, &tmp);
            ge_tobytes(single_bytes.data() + i * 32, &p2);
        }

        // Batch results
        std::vector<ge_p2> batch_results(count);
        ge_scalarmult_ct_batch(batch_results.data(), scalars.data(), points.data(), count);

        for (size_t i = 0; i < count; i++)
        {
            unsigned char batch_bytes[32];
            ge_tobytes(batch_bytes, &batch_results[i]);
            std::string name = "CT batch=single N=" + std::to_string(count) + " i=" + std::to_string(i);
            check_bytes(name.c_str(), single_bytes.data() + i * 32, batch_bytes, 32);
        }
    }

    // Test batch DSM matches single-op for N=1..8
    for (size_t count = 1; count <= 8; count++)
    {
        std::vector<unsigned char> a_scalars(count * 32);
        std::vector<unsigned char> b_scalars(count * 32);
        std::vector<ge_p3> A_points(count);
        for (size_t i = 0; i < count; i++)
        {
            for (int j = 0; j < 32; j++)
            {
                a_scalars[i * 32 + j] = static_cast<unsigned char>((i * 83 + j * 29 + 3) & 0xFF);
                b_scalars[i * 32 + j] = static_cast<unsigned char>((i * 97 + j * 43 + 19) & 0xFF);
            }
            a_scalars[i * 32 + 31] &= 0x7F;
            b_scalars[i * 32 + 31] &= 0x7F;

            unsigned char base_scalar[32];
            for (int j = 0; j < 32; j++)
                base_scalar[j] = static_cast<unsigned char>((i * 101 + j * 37 + 41) & 0xFF);
            base_scalar[0] &= 248;
            base_scalar[31] &= 127;
            base_scalar[31] |= 64;
            ge_p1p1 tmp;
            ge_scalarmult_base_ct(&tmp, base_scalar);
            ge_p1p1_to_p3(&A_points[i], &tmp);
        }

        // Single-op results
        std::vector<unsigned char> single_bytes(count * 32);
        for (size_t i = 0; i < count; i++)
        {
            ge_p1p1 tmp;
            ge_double_scalarmult_base_negate_vartime(
                &tmp, a_scalars.data() + i * 32, &A_points[i], b_scalars.data() + i * 32);
            ge_p2 p2;
            ge_p1p1_to_p2(&p2, &tmp);
            ge_tobytes(single_bytes.data() + i * 32, &p2);
        }

        // Batch results
        std::vector<ge_p2> batch_results(count);
        ge_double_scalarmult_base_negate_vartime_batch(
            batch_results.data(), a_scalars.data(), A_points.data(), b_scalars.data(), count);

        for (size_t i = 0; i < count; i++)
        {
            unsigned char batch_bytes[32];
            ge_tobytes(batch_bytes, &batch_results[i]);
            std::string name = "DSM batch=single N=" + std::to_string(count) + " i=" + std::to_string(i);
            check_bytes(name.c_str(), single_bytes.data() + i * 32, batch_bytes, 32);
        }
    }
}


